import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.LX5S0jbT.js";const k=JSON.parse('{"title":"Run Pi on Android with Termux","description":"","frontmatter":{},"headers":[],"relativePath":"termux.md","filePath":"termux.md"}'),n={name:"termux.md"};function o(l,s,r,p,h,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="run-pi-on-android-with-termux" tabindex="-1">Run Pi on Android with Termux <a class="header-anchor" href="#run-pi-on-android-with-termux" aria-label="Permalink to &quot;Run Pi on Android with Termux&quot;">​</a></h1><p>Pi runs on Android through <a href="https://termux.dev/" target="_blank" rel="noreferrer">Termux</a>, a terminal emulator and Linux environment. Text input, file tools, and shell commands are supported. Pi can copy and paste text through the Android clipboard with Termux:API. Clipboard image paste is not supported.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Install Termux from <a href="https://github.com/termux/termux-app#installation" target="_blank" rel="noreferrer">GitHub or F-Droid</a>. Do not use the deprecated Google Play build.</p><p><a href="https://github.com/termux/termux-api#installation" target="_blank" rel="noreferrer">Termux:API</a> is optional. Install it only when you want Pi to copy or paste Android clipboard text, or when shell commands need Android device APIs.</p><h2 id="install-pi" tabindex="-1">Install Pi <a class="header-anchor" href="#install-pi" aria-label="Permalink to &quot;Install Pi&quot;">​</a></h2><ol><li><p>Update Termux packages:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div></li><li><p>Install Node.js and Git:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodejs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div></li><li><p>Install Pi:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @earendil-works/pi-coding-agent</span></span></code></pre></div></li><li><p>Verify the installation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div></li><li><p>Open the folder you want to work in and start Pi:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/working-folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span></span></code></pre></div></li></ol><p>Continue with the main <a href="./quickstart.html#3-choose-a-model">Quickstart</a> to connect a model and run your first task.</p><h2 id="access-android-shared-storage" tabindex="-1">Access Android shared storage <a class="header-anchor" href="#access-android-shared-storage" aria-label="Permalink to &quot;Access Android shared storage&quot;">​</a></h2><p>Termux cannot access shared Android storage until you grant permission. Run this once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">termux-setup-storage</span></span></code></pre></div><p>After approval, Android shared storage is available under <code>/storage/emulated/0</code> and through the links Termux creates under <code>~/storage/</code>.</p><p>Only grant this permission when Pi should be able to access those files. Commands and tools running in Termux use the same storage permissions as the Termux process.</p><h2 id="use-clipboard-commands" tabindex="-1">Use clipboard commands <a class="header-anchor" href="#use-clipboard-commands" aria-label="Permalink to &quot;Use clipboard commands&quot;">​</a></h2><p>Pi uses <code>termux-clipboard-set</code> to copy text and <code>termux-clipboard-get</code> for its clipboard-paste shortcut. Shell commands can use both commands directly. Install the Termux:API app and its command-line package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> termux-api</span></span></code></pre></div><p>Verify the integration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Pi clipboard test&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> termux-clipboard-set</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">termux-clipboard-get</span></span></code></pre></div><p>The second command should print <code>Pi clipboard test</code>.</p><p>The Termux clipboard API supports text only. Pi&#39;s clipboard-paste shortcut inserts that text into the editor but cannot attach clipboard images.</p><h2 id="add-termux-specific-instructions" tabindex="-1">Add Termux-specific instructions <a class="header-anchor" href="#add-termux-specific-instructions" aria-label="Permalink to &quot;Add Termux-specific instructions&quot;">​</a></h2><p>Pi detects that it is running in Termux, but it cannot infer how you want it to interact with Android. Add only the environment details relevant to your work to <code>~/.pi/agent/AGENTS.md</code>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Termux environment</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pi runs in Termux on Android.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Shared Android storage is under </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`/storage/emulated/0\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Open URLs with </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`termux-open-url &quot;https://example.com&quot;\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Open files with </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`termux-open &lt;path&gt;\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not access shared storage unless the task requires it.</span></span></code></pre></div><p>Run <code>/reload</code> after changing the file during an active session.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="clipboard-integration-fails" tabindex="-1">Clipboard integration fails <a class="header-anchor" href="#clipboard-integration-fails" aria-label="Permalink to &quot;Clipboard integration fails&quot;">​</a></h3><p>Confirm that you installed both components:</p><ol><li>The Termux:API Android app from the same source as Termux</li><li>The <code>termux-api</code> command-line package</li></ol><p>Then run the clipboard verification commands above outside Pi. If they fail there, fix the Termux:API installation before retrying Pi&#39;s copy command.</p><h3 id="shared-storage-reports-permission-denied" tabindex="-1">Shared storage reports permission denied <a class="header-anchor" href="#shared-storage-reports-permission-denied" aria-label="Permalink to &quot;Shared storage reports permission denied&quot;">​</a></h3><p>Run <code>termux-setup-storage</code>, approve the Android permission request, and retry the path under <code>~/storage/</code> or <code>/storage/emulated/0</code>.</p><h3 id="pi-is-not-found-after-installation" tabindex="-1">Pi is not found after installation <a class="header-anchor" href="#pi-is-not-found-after-installation" aria-label="Permalink to &quot;Pi is not found after installation&quot;">​</a></h3><p>Open a new Termux shell and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prefix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pi</span></span></code></pre></div><p>Confirm that the global npm binary directory is on <code>PATH</code>, then reinstall Pi if the package is missing.</p>`,35)])])}const u=i(n,[["render",o]]);export{k as __pageData,u as default};
